75: static void free_buff_in(void *buf_in)
76: {
77: 	if (!buf_in)
78: 		return;
79: 
80: 	kfree(buf_in);
81: }
82: 
83: static int alloc_buff_in(struct msg_module *nt_msg, u32 in_size, void **buf_in)
84: {
85: 	void *msg_buf;
86: 
87: 	if (!in_size)
88: 		return 0;
89: 
90: 	if (in_size > MAX_MSG_IN_SIZE) {
91: 		pr_err("msg in size(%u) more than %u\n",
92: 		       in_size, MAX_MSG_IN_SIZE);
93: 		return -ENOMEM;
94: 	}
95: 
96: 	msg_buf = kzalloc((unsigned long)in_size, GFP_KERNEL);
97: 	*buf_in = msg_buf;
98: 	if (ZERO_OR_NULL_PTR(*buf_in)) {
99: 		pr_err("alloc buf_in failed\n");
100: 		return -ENOMEM;
101: 	}
102: 
103: 	if (copy_from_user(msg_buf, nt_msg->in_buff, (unsigned long)in_size)) {
104: 		pr_err("Copy from user failed in %s function\n", __func__);
105: 		kfree(msg_buf);
106: 		return -EFAULT;
107: 	}
108: 
109: 	return 0;
110: }
