152: static int hns3_cae_netdev_match_check(struct net_device *netdev)
153: {
154: 	struct ethtool_drvinfo drv_info;
155: 
156: 	if (netdev->ethtool_ops->get_drvinfo)
157: 		netdev->ethtool_ops->get_drvinfo(netdev, &drv_info);
158: 
159: 	if (!strncmp(drv_info.driver, hns3_driver_name,
160: 		     strlen(hns3_driver_name)))
161: 		return 0;
162: 
163: 	netdev_err(netdev, "match hns3 driver name(%s) failed\n",
164: 		   drv_info.driver);
165: 	return -1;
166: }
