182: static struct net_device *get_netdev_by_ifname(char *ifname)
183: {
184: 	struct socket *temp_sock = NULL;
185: 	struct net_device *netdev = NULL;
186: 	struct ifreq ifr;
187: 	int err;
188: 
189: 	err = sock_create(PF_INET, SOCK_DGRAM, 0, &temp_sock);
190: 	if (err < 0) {
191: 		pr_err("fail to enter sock_create, err = %d\n", err);
192: 		return NULL;
193: 	}
194: 
195: 	strncpy(ifr.ifr_ifrn.ifrn_name, ifname, (unsigned long)IFNAMSIZ);
196: 	kernel_sock_ioctl(temp_sock, SIOCSIFNAME, (unsigned long)&ifr);
197: 	netdev = dev_get_by_name(sock_net(temp_sock->sk), ifname);
198: 	if (!netdev)
199: 		goto out;
